input.command:
printf '%s\n' '--- zone/carriers ---'; python3 - <<'PY'
import csv
for f in ['data/pickup_zones.csv','data/carriers.csv']:
 print('\n'+f)
 with open(f,newline='') as x:
  rows=list(csv.DictReader(x))
  for r in rows:
   if f.endswith('pickup_zones.csv') and r.get('zone')=='47': print(r)
   if f.endswith('carriers.csv') and (r.get('kind')=='trucker' and '47' in (r.get('serves') or '').split() or r.get('kind')=='airline' and 'NBO' in (r.get('serves') or '').split()): print(r)
PY
printf '\n--- API docs ---\n'; cat knowledge/api.md; printf '\n--- tool README ---\n'; cat tools/README.md; printf '\n--- quote ---\n'; python3 tools/quote_air.py ? NBO 1061 5.97 --date 2026-11-26

